  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, which shares the oxindole core and a basic amine-containing side chain with the query, has an absolute oral bioavailability of about 60% in the fed state and 30% in the fasted state in humans, both above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Psilocybin, containing a tertiary aminoethyl indole motif analogous to the query's dipropylaminoethyl side chain, has an absolute oral bioavailability of 52.7% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Primidone, an aromatic amide/lactam drug, is reported to have oral bioavailability greater than 90% in humans, supporting high F despite lower structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DMT, a related tertiary aminoethyl indole, has only 10-15% oral bioavailability due to extensive first-pass MAO metabolism; this is the only low-F analogue, but its mechanism and scaffold differ from the query and do not outweigh the high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ropinirole, a non-ergoline dopamine agonist with an oxindole core and dipropylaminoethyl side chain. The most transferable analogues—ziprasidone (same oxindole scaffold, F 30-60%), psilocybin/psilocin (tertiary aminoethyl indole, F ~55%), and several aromatic lactam drugs (F >80%)—all support F ≥20%. The only low-F analogue, DMT, is poorly transferable because its low bioavailability is driven by MAO-mediated first-pass metabolism not applicable to ropinirole. Therefore predict high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for ropinirole was supplied in the evidence set.",
    "Morgan similarity scores are low (0.22-0.26), so structural transfer relies on chemical analogy rather than high fingerprint overlap.",
    "Food effects and dose-dependent first-pass metabolism for the query are not directly captured by the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

